; addr.asm -- appendix D: every entry of the tables, photographed
; generated by genD.py
        INCLUDE "msx.inc"
        OUTPUT "addr.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Six passes, each with the screen set up again with the display off. In
; each frame one byte is written at the address one entry of a table gives,
; and the one before is put back, so that the next frame's photograph shows
; where that address is on the screen, and nothing else.
init:   di
        ld sp, SYS_AREA
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2

; pass pb: the patterns, the BIOS layout
; (192 entries of patrow: $FF written at one a frame, $00 put back)
pb:     di
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; backdrop
        VRAM_WRITE $0000        ; patterns: $00
        ld bc, 6144
.p:     ld a, $00
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .p
        VRAM_WRITE $2000        ; colours: $1F
        ld bc, 6144
.c:     ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
.n:     xor a
.n1:    out (VDP_DATA), a
        inc a
        jr nz, .n1
        djnz .n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $E0          ; display on, the frame interrupt on
        ld hl, patrow
        ld e, (hl)              ; DE: the first entry, for the first put-back
        inc hl
        ld d, (hl)
        dec hl
        ld b, 192
        in a, (VDP_CTRL)
        ei
        halt                    ; a frame of the screen as it is
pbs:    halt                    ; the end of a frame's paper
        di
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; the last entry back
        ld a, $00
        out (VDP_DATA), a
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; this entry
        ld a, $FF
        out (VDP_DATA), a
        nop                     ; the VDP takes it meanwhile
        nop
pbm:    ei                      ; measD.py's mark: the frame after shows it
        djnz pbs
        halt
        di
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; the last entry back
        ld a, $00
        out (VDP_DATA), a

; pass cb: the colours, the BIOS layout
; (192 entries of colrow: $1F written at one a frame, $FF put back)
cb:     di
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
