        in a, (VDP_CTRL)
        ei
        halt                    ; a frame of the screen as it is
cbs:    halt                    ; the end of a frame's paper
        di
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; the last entry back
        ld a, $FF
        out (VDP_DATA), a
        ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; this entry
