        ld a, d
        or $40
        out (VDP_CTRL), a       ; the last entry back
        ld a, $FF
        out (VDP_DATA), a

; pass p3: the patterns, one set for the three thirds
; (192 entries of patrow3: $FF written at one a frame, $00 put back)
p3:     di
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $9F          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; backdrop
