; pass nb: the names, the BIOS layout
; (24 entries of namerow: $01 written at one a frame, $00 put back)
nb:     di
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; backdrop
        VRAM_WRITE $0000        ; patterns: $00
        ld bc, 6144
.p:     ld a, $00
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .p
        VRAM_WRITE $2000        ; colours: $1F
        ld bc, 6144
.c:     ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .c
        VRAM_WRITE $1800        ; names: all 0
        ld bc, 768
.n:     xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $E0          ; display on, the frame interrupt on
        VRAM_WRITE $0008        ; shape 1 of third 0: solid
        ld b, 8
.s0:    ld a, $FF
        out (VDP_DATA), a
        djnz .s0
        VRAM_WRITE $0808        ; shape 1 of third 1: solid
        ld b, 8
.s1:    ld a, $FF
        out (VDP_DATA), a
        djnz .s1
        VRAM_WRITE $1008        ; shape 1 of third 2: solid
        ld b, 8
.s2:    ld a, $FF
        out (VDP_DATA), a
        djnz .s2
        ld hl, namerow
        ld e, (hl)              ; DE: the first entry, for the first put-back
